#include "th10/game/event_script_runtime.hpp"
#include <algorithm>
namespace th10::event_script {
// Semantic reconstruction of retail 0x0040BD80.
int EndingScript_Update(EndingState&s,const std::vector<EndingCommand>&v,float speed,const EndingEdges&e){if(s.flags&4)return 0;while(s.cursor<(int)v.size()&&v[s.cursor].time<=s.time){const auto&c=v[s.cursor];switch(c.opcode){case 0:return-1;case 3:s.wait_counter=(s.wait_counter+1)%5;break;case 4:s.wait_counter=0;break;case 5:if(!e.confirm||!e.confirm(e.context)){++s.wait_counter;return 0;}s.wait_counter=0;break;case 6:if(!e.confirm||!e.confirm(e.context)){++s.wait_counter;return 0;}s.wait_counter=0;s.flags&=~1u;break;case 7:s.flags|=4u;if(e.event)e.event(e.context,7,c);++s.cursor;return 0;case 8:if(c.args.size()>1){int d=c.args[0],slot=c.args[1];if(slot>=0&&slot<5)s.handles[slot]=d;}break;case 9:if(!c.args.empty())s.color=(std::uint32_t)c.args[0];break;case 10:case 11:case 13:case 14:case 15:case 16:case 17:if(e.event)e.event(e.context,c.opcode,c);break;case 12:s={};s.flags=2;s.color=0xffffff;break;default:break;}++s.cursor;}s.previous_time=s.time;if(speed>.99f&&speed<1.01f){++s.time;++s.fraction;}else{s.fraction+=(int)(speed*1000);s.time=s.fraction/1000;}return 0;}
// Semantic reconstruction of retail 0x00403C80.
int StageTimeline_Update(StageState&s,const std::vector<StageCommand>&v,float speed,const StageEdges&e){while(s.cursor<(int)v.size()&&v[s.cursor].time<=s.time){const auto&c=v[s.cursor];auto a=[&](int i){return i<(int)c.args.size()?c.args[i]:0.f;};switch(c.opcode){case 0:s.cursor=v.size();break;case 1:s.time=(int)a(0);s.previous_time=s.time-1;s.fraction=s.time*1000;break;case 2:for(int i=0;i<3;++i){float old=s.camera[i];s.camera[i]=a(i);s.camera_delta[i]=s.camera[i]-old;}break;case 3:s.target=s.camera;for(int i=0;i<3;++i)s.target_delta[i]=a(i);s.mode=(int)a(3);break;case 4:for(int i=0;i<3;++i)s.target[i]=a(i);break;case 5:s.up=s.target;for(int i=0;i<3;++i)s.target_delta[i]=a(i);s.mode=(int)a(3);break;case 6:for(int i=0;i<3;++i)s.up[i]=a(i);break;case 7:s.shake=a(0);break;case 8:s.color=(std::uint32_t)a(0);for(int i=0;i<4;++i)s.color_channels[i]=float((s.color>>(i*8))&255);break;case 9:if(e.event)e.event(e.context,9,c);s.flags|=1;break;case 10:case 11:s.mode=8;for(int i=0;i<3;++i)s.target_delta[i]=a(i+3);break;case 12:s.mode=(int)a(0);break;case 13:s.global_value=(int)a(0);break;case 14:s.flags=(a(1)<0)?(s.flags&~1u):(s.flags|1u);break;}++s.cursor;}s.previous_time=s.time;if(speed>.99f&&speed<1.01f){++s.time;++s.fraction;}else{s.fraction+=(int)(speed*1000);s.time=s.fraction/1000;}return 0;}
}
